-- ===========================================================================
-- Hand-written part (prisma/README.md). Phase 2 M3: assignment history, round-robin state,
-- in-app notifications. Runs as crm_migrator. Policies and grants for the new tables only,
-- plus one widened CHECK on lead_activity.type ('ASSIGNED', domain-model §2.2).
-- ===========================================================================

-- ---------------------------------------------------------------------------
-- 1. Integrity
-- ---------------------------------------------------------------------------
ALTER TABLE lead_assignment_history
  ADD CONSTRAINT lead_assignment_history_source CHECK (source IN
    ('MANUAL', 'BULK', 'IMPORT', 'ROUND_ROBIN', 'RULE', 'LEAVE_COVER', 'DEACTIVATION', 'MERGE')),
  ADD CONSTRAINT lead_assignment_history_target CHECK (user_id IS NOT NULL OR team_id IS NOT NULL),
  ADD CONSTRAINT lead_assignment_history_valid_range CHECK (ended_at IS NULL OR ended_at >= started_at),
  ADD CONSTRAINT lead_assignment_history_reason_length CHECK (reason IS NULL OR length(reason) <= 500),
  -- Workflow G acceptance: contiguous, non-overlapping spells per lead (btree_gist).
  ADD CONSTRAINT lead_assignment_history_no_overlap
    EXCLUDE USING gist (lead_id WITH =, tstzrange(started_at, ended_at, '[)') WITH &&);
CREATE UNIQUE INDEX lead_assignment_history_open_uq ON lead_assignment_history (lead_id)
  WHERE ended_at IS NULL;

ALTER TABLE notification
  ADD CONSTRAINT notification_type CHECK (type IN
    ('LEAD_ASSIGNED', 'LEADS_ASSIGNED_DIGEST', 'LEADS_REASSIGNED_AWAY', 'LEAD_RETURNING_ENQUIRY')),
  ADD CONSTRAINT notification_text_length CHECK (length(title) <= 200 AND length(body) <= 500),
  ADD CONSTRAINT notification_link_internal CHECK (link IS NULL OR link ~ '^/app/[A-Za-z0-9/_?=&%-]*$');

ALTER TABLE lead_activity DROP CONSTRAINT lead_activity_type;
ALTER TABLE lead_activity
  ADD CONSTRAINT lead_activity_type
    CHECK (type IN ('CREATED', 'ENQUIRY', 'ASSIGNED', 'STAGE', 'NOTE', 'FIELD_CHANGED'));

-- ---------------------------------------------------------------------------
-- 2. RLS: ENABLE + FORCE, maintenance, tenant isolation (same text as 0002/0003)
-- ---------------------------------------------------------------------------
DO $$
DECLARE t text;
BEGIN
  FOREACH t IN ARRAY ARRAY['lead_assignment_history', 'team_assignment_state', 'notification'] LOOP
    EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t);
    EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t);
    EXECUTE format('CREATE POLICY maintenance ON %I FOR ALL TO crm_migrator USING (true) WITH CHECK (true)', t);
    EXECUTE format(
      'CREATE POLICY tenant_isolation ON %I FOR ALL TO crm_app '
      'USING (org_id = (SELECT app.current_org_id())) '
      'WITH CHECK (org_id = (SELECT app.current_org_id()))', t);
  END LOOP;
END $$;

-- Assignment spells: attributed to the session user, opened and closed at the transaction time,
-- closed at most once. RESTRICTIVE: they narrow tenant_isolation, never widen it.
CREATE POLICY actor_is_session_user ON lead_assignment_history AS RESTRICTIVE FOR INSERT TO crm_app
  WITH CHECK (assigned_by IS NOT DISTINCT FROM (SELECT app.current_user_id())
              AND started_at = now() AND ended_at IS NULL);
CREATE POLICY close_once_now ON lead_assignment_history AS RESTRICTIVE FOR UPDATE TO crm_app
  USING (ended_at IS NULL)
  WITH CHECK (ended_at = now());

-- Notifications: written only by system actors (the worker: no app.user_id), read and marked
-- only by their recipient.
CREATE POLICY system_writes ON notification AS RESTRICTIVE FOR INSERT TO crm_app
  WITH CHECK ((SELECT app.current_user_id()) IS NULL);
CREATE POLICY recipient_reads ON notification AS RESTRICTIVE FOR SELECT TO crm_app
  USING (recipient_user_id = (SELECT app.current_user_id()));
CREATE POLICY recipient_marks ON notification AS RESTRICTIVE FOR UPDATE TO crm_app
  USING (recipient_user_id = (SELECT app.current_user_id()))
  WITH CHECK (recipient_user_id = (SELECT app.current_user_id()));

-- ---------------------------------------------------------------------------
-- 3. crm_app grants (minimum). No DELETE. crm_auth / crm_platform get nothing.
-- ---------------------------------------------------------------------------
GRANT SELECT, INSERT ON lead_assignment_history TO crm_app;
GRANT UPDATE (ended_at) ON lead_assignment_history TO crm_app;
GRANT SELECT, INSERT ON team_assignment_state TO crm_app;
GRANT UPDATE (last_assigned_membership_id, updated_at) ON team_assignment_state TO crm_app;
GRANT SELECT, INSERT ON notification TO crm_app;
GRANT UPDATE (read_at) ON notification TO crm_app;

-- ---------------------------------------------------------------------------
-- 4. Backfill (idempotent): M1 leads were assigned once, to their creator's choice, at
--    creation; no later ownership change existed before this migration. One open spell from
--    created_at for every lead with an owner or team and no spell yet. Leads with neither get
--    no spell (nothing to record). Nothing else is inferred.
-- ---------------------------------------------------------------------------
INSERT INTO lead_assignment_history (org_id, lead_id, user_id, team_id, started_at, assigned_by, source, reason)
SELECT l.org_id, l.id, l.owner_user_id, l.team_id, l.created_at, l.created_by, 'MANUAL',
       'Recorded from lead creation (migration 0004 backfill)'
FROM lead l
WHERE (l.owner_user_id IS NOT NULL OR l.team_id IS NOT NULL)
  AND NOT EXISTS (SELECT 1 FROM lead_assignment_history h WHERE h.lead_id = l.id);
